/* Listing browser: reads window.FUNDIT_DATA generated by scripts/export_site_data.py. */
const FUNDIT_DATA = window.FUNDIT_DATA || null;
const ALL_LISTINGS = FUNDIT_DATA && Array.isArray(FUNDIT_DATA.listings) ? FUNDIT_DATA.listings : [];
const RESIDENTIAL_TYPES = new Set(['single_family', 'condo', 'townhouse', 'manufactured', 'duplex']);
const SPECIAL_TYPES = new Set(['auction', 'foreclosure', 'bank_owned']);
const TYPE_LABELS = { single_family: 'Single-family', condo: 'Condo', townhouse: 'Townhouse', manufactured: 'Manufactured', duplex: 'Duplex', multi_family: 'Multifamily', land: 'Land', other: 'Other' };
const SPECIAL_LABELS = { auction: 'Auction', foreclosure: 'Foreclosure', bank_owned: 'Bank-owned', new_construction: 'New construction', fsbo: 'For sale by owner' };
let listingLimit = 24;
let filteredListings = [];

const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const fmtNum = (value, suffix = '') => {
  if (value === null || value === undefined || value === '') return '—';
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? `${number.toLocaleString('en-US', { maximumFractionDigits: 1 })}${suffix}` : '—';
};
const typeLabel = value => TYPE_LABELS[value] || (value ? value.replace(/_/g, ' ').replace(/\b\w/g, ch => ch.toUpperCase()) : 'Unknown');
const unitLabel = value => {
  const text = String(value || '').trim();
  return text ? (text.startsWith('#') ? text : `#${text}`) : '';
};
const unitSuffix = listing => {
  const unit = unitLabel(listing.unit);
  if (!unit) return '';
  const plain = unit.replace(/^#/, '');
  const present = new RegExp(`(^|[\s#])${plain}([\s#]|$)`, 'i').test(String(listing.street || ''));
  return present ? '' : unit;
};
const monthLabel = value => {
  if (!value || !/^\d{4}-\d{2}$/.test(value)) return 'date unknown';
  const [year, month] = value.split('-').map(Number);
  return new Date(year, month - 1, 1).toLocaleString('en-US', { month: 'long', year: 'numeric' });
};
const hoaLabel = value => value === null || value === undefined ? 'HOA unknown' : Number(value) === 0 ? 'No HOA listed' : `${money(Number(value))}/mo HOA`;
const median = values => {
  const sorted = [...values].sort((a, b) => a - b);
  if (!sorted.length) return 0;
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
};

function initListings() {
  const countEl = $('#listingNavCount');
  const metaEl = $('#listingDataMeta');
  if (!FUNDIT_DATA || !ALL_LISTINGS.length) {
    if (metaEl) metaEl.textContent = 'Listing data not loaded. Run python3 scripts/export_site_data.py, then reload.';
    if (countEl) countEl.textContent = '—';
    $('#listingGrid').innerHTML = '<div class="listing-empty"><h2>Listing data not loaded.</h2><p>Generate the static snapshot with <code>python3 scripts/export_site_data.py</code> from the project root, then reload.</p></div>';
    ['marketCount', 'marketMedian', 'marketCities', 'listingResultCount'].forEach(id => {
      const el = $('#' + id);
      if (el) el.textContent = '—';
    });
    return;
  }

  const cities = [...new Set(ALL_LISTINGS.map(listing => listing.city).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  $('#listingCity').insertAdjacentHTML('beforeend', cities.map(city => `<option value="${esc(city)}">${esc(city)}</option>`).join(''));

  const types = [...new Set(ALL_LISTINGS.map(listing => listing.property_type).filter(Boolean))].sort();
  $('#listingType').insertAdjacentHTML('beforeend', types.map(type => `<option value="${esc(type)}">${esc(typeLabel(type))}</option>`).join(''));

  const prices = ALL_LISTINGS.map(listing => Number(listing.price)).filter(price => Number.isFinite(price) && price > 0);
  const priceMedian = median(prices);
  $('#marketCount').textContent = ALL_LISTINGS.length.toLocaleString();
  $('#marketMedian').textContent = priceMedian ? money(priceMedian) : '—';
  $('#marketCities').textContent = cities.length.toLocaleString();
  if (countEl) countEl.textContent = Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(ALL_LISTINGS.length);
  if (metaEl) metaEl.textContent = `${ALL_LISTINGS.length.toLocaleString()} candidates · ${monthLabel(FUNDIT_DATA.data_as_of)} · ${FUNDIT_DATA.license || 'CC0'} snapshot`;

  document.querySelectorAll('[data-listing-source]').forEach(link => {
    if (FUNDIT_DATA.source) link.href = FUNDIT_DATA.source;
  });

  const onChange = () => renderListings(true);
  ['listingSearch', 'listingBeds', 'listingBaths', 'listingMinPrice', 'listingMaxPrice', 'listingMaxHoa'].forEach(id => {
    const el = $('#' + id);
    if (el) el.addEventListener('input', onChange);
  });
  ['listingCity', 'listingType', 'listingSort', 'listingSpecial'].forEach(id => {
    const el = $('#' + id);
    if (el) el.addEventListener('change', onChange);
  });
  $('#clearListingFilters').addEventListener('click', resetListingFilters);
  $('#loadMoreListings').addEventListener('click', () => {
    listingLimit += 24;
    renderListings();
  });
  $('#listingGrid').addEventListener('click', event => {
    const detail = event.target.closest('[data-listing-detail]');
    const use = event.target.closest('[data-listing-use]');
    if (detail) {
      const listing = ALL_LISTINGS.find(item => item.id === detail.dataset.listingDetail);
      if (listing) showListingDetail(listing);
    }
    if (use) {
      const listing = ALL_LISTINGS.find(item => item.id === use.dataset.listingUse);
      if (listing) useListing(listing);
    }
  });
  $('#stepContent').addEventListener('click', event => {
    if (event.target.id === 'findListings') {
      applyProfileToListings();
      view('listings');
      toast('Listing filters set from your profile. Verify every listing before relying on it.');
    }
  });
  ['rate', 'down'].forEach(id => {
    const el = $('#' + id);
    if (el) el.addEventListener('input', () => {
      if (!$('#listings').classList.contains('hidden')) renderListings();
    });
  });

  renderListings(true);
}

function renderListings(reset = false) {
  if (reset) listingLimit = 24;
  const search = ($('#listingSearch').value || '').trim().toLowerCase();
  const city = $('#listingCity').value;
  const type = $('#listingType').value;
  const minPrice = Number($('#listingMinPrice').value) || 0;
  const maxPrice = Number($('#listingMaxPrice').value) || 0;
  const minBeds = Number($('#listingBeds').value) || 0;
  const minBaths = Number($('#listingBaths').value) || 0;
  const maxHoa = Number($('#listingMaxHoa').value) || 0;
  const includeSpecial = $('#listingSpecial').checked;
  const sort = $('#listingSort').value;

  filteredListings = ALL_LISTINGS.filter(listing => {
    const price = Number(listing.price);
    if (!Number.isFinite(price) || price <= 0) return false;
    if (search && !`${listing.street} ${listing.city} ${listing.zip}`.toLowerCase().includes(search)) return false;
    if (city !== 'all' && listing.city !== city) return false;
    if (type === 'residential') {
      if (!RESIDENTIAL_TYPES.has(listing.property_type)) return false;
    } else if (type !== 'all' && listing.property_type !== type) {
      return false;
    }
    if (minPrice && price < minPrice) return false;
    if (maxPrice && price > maxPrice) return false;
    if (minBeds && (Number(listing.bedrooms) || 0) < minBeds) return false;
    if (minBaths && (Number(listing.bathrooms) || 0) < minBaths) return false;
    if (maxHoa && listing.hoa !== null && Number(listing.hoa) > maxHoa) return false;
    if (!includeSpecial && SPECIAL_TYPES.has(listing.listing_type)) return false;
    return true;
  });

  filteredListings.sort((a, b) => {
    if (sort === 'price-desc') return Number(b.price) - Number(a.price);
    if (sort === 'sqft-desc') return (Number(b.square_feet) || 0) - (Number(a.square_feet) || 0);
    if (sort === 'beds-desc') return (Number(b.bedrooms) || 0) - (Number(a.bedrooms) || 0);
    return Number(a.price) - Number(b.price);
  });

  const total = filteredListings.length;
  const shown = filteredListings.slice(0, listingLimit);
  $('#listingResultCount').textContent = `${total.toLocaleString()} candidate${total === 1 ? '' : 's'}`;
  $('#listingResultNote').textContent = total ? `Showing ${shown.length.toLocaleString()}` : '';
  $('#loadMoreListings').hidden = total <= listingLimit;
  $('#listingGrid').innerHTML = shown.length ? shown.map(listingCard).join('') : emptyState();
  const resetButton = $('#emptyReset');
  if (resetButton) resetButton.onclick = resetListingFilters;
}

function listingCard(listing) {
  const special = SPECIAL_LABELS[listing.listing_type];
  const estimate = monthlyEstimate(listing);
  const badge = special ? `<span class="badge amber">${esc(special)}</span>` : `<span class="badge neutral">${esc(typeLabel(listing.property_type))}</span>`;
  const unit = unitSuffix(listing);
  const hoa = hoaLabel(listing.hoa);
  return `<article class="listing-card">
    <div class="listing-card-top">${badge}<span class="listing-price">${money(Number(listing.price))}</span></div>
    <h3>${esc(listing.street)}${unit ? ` <small>${esc(unit)}</small>` : ''}</h3>
    <p class="listing-location">${esc(listing.city)}, CA ${esc(listing.zip || '')}</p>
    <div class="listing-facts"><span>${fmtNum(listing.bedrooms, ' bd')}</span><span>${fmtNum(listing.bathrooms, ' ba')}</span><span>${fmtNum(listing.square_feet, ' sqft')}</span></div>
    <div class="listing-hoa">${esc(hoa)}</div>
    <div class="listing-cost"><div><small>Est. monthly</small><b>${money(estimate.total)}</b></div><small>P&amp;I + tax/ins${estimate.hoaKnown ? ' + HOA' : ''}; not a quote</small></div>
    <div class="listing-actions"><button type="button" data-listing-detail="${esc(listing.id)}">Details</button><button type="button" data-listing-use="${esc(listing.id)}">Use in gap calculator →</button></div>
  </article>`;
}

function emptyState() {
  return '<div class="listing-empty"><h2>No candidates match.</h2><p>Widen the price range, choose another city or include auction, foreclosure and bank-owned listings. The dataset is a snapshot; it does not contain every home for sale.</p><button type="button" class="secondary" id="emptyReset">Reset filters</button></div>';
}

function resetListingFilters() {
  $('#listingSearch').value = '';
  $('#listingCity').value = 'all';
  $('#listingType').value = 'residential';
  $('#listingBeds').value = '0';
  $('#listingBaths').value = '0';
  $('#listingMinPrice').value = '50000';
  $('#listingMaxPrice').value = '1500000';
  $('#listingMaxHoa').value = '1000';
  $('#listingSort').value = 'price-asc';
  $('#listingSpecial').checked = false;
  renderListings(true);
  toast('Listing filters reset');
}

function monthlyEstimate(listing) {
  const price = Number(listing.price) || 0;
  const down = Math.min(get('down'), price);
  const rate = get('rate') || 6.5;
  const loan = Math.max(0, price - down);
  const monthlyRate = rate / 1200;
  const pi = monthlyRate ? loan * monthlyRate / (1 - Math.pow(1 + monthlyRate, -360)) : loan / 360;
  const tax = price * 0.01 / 12;
  const insurance = price * 0.0035 / 12;
  const hoa = listing.hoa === null || listing.hoa === undefined ? 0 : Number(listing.hoa) || 0;
  return { total: pi + tax + insurance + hoa, hoaKnown: listing.hoa !== null && listing.hoa !== undefined, pi, tax, insurance, hoa, down, rate };
}

function showListingDetail(listing) {
  const estimate = monthlyEstimate(listing);
  const unit = unitSuffix(listing);
  const fields = [
    ['Price', money(Number(listing.price))],
    ['Address', `${listing.street}${unit ? ' ' + unit : ''}`],
    ['City', `${listing.city}, CA ${listing.zip || ''}`],
    ['Property type', typeLabel(listing.property_type)],
    ['Beds', fmtNum(listing.bedrooms)],
    ['Baths', fmtNum(listing.bathrooms)],
    ['Square feet', fmtNum(listing.square_feet)],
    ['HOA', hoaLabel(listing.hoa)],
    ['Listing type', SPECIAL_LABELS[listing.listing_type] || 'Standard'],
    ['Source status', listing.status || 'unknown'],
    ['Source ID', listing.id],
    ['Est. monthly', money(estimate.total)]
  ];
  showModal(`<span class="badge green">CC0 snapshot</span><h1 style="margin-top:18px">${esc(listing.street)}</h1><p>${esc(listing.city)}, CA ${esc(listing.zip || '')} · ${esc(typeLabel(listing.property_type))}</p><div class="listing-detail-grid">${fields.map(([label, value]) => `<div><small>${esc(label)}</small><b>${esc(value)}</b></div>`).join('')}</div><p class="muted">Estimate uses the calculator rate and down payment, 1.0% annual property tax, 0.35% annual insurance and the listed HOA. It is not a lender quote. Availability, tenure, condition and HOA are unverified.</p><p class="muted">Snapshot data as of ${esc(monthLabel(FUNDIT_DATA.data_as_of))}. Source: RealEstateDataset (CC0).</p><button type="button" class="primary" id="detailUseListing">Use price in gap calculator →</button>`);
  $('#detailUseListing').onclick = () => {
    $('#modal').close();
    useListing(listing);
  };
}

function useListing(listing) {
  $('#calcProject').textContent = `${listing.street}, ${listing.city}`;
  $('#cost').value = Math.round(Number(listing.price));
  view('projects');
  calculate();
  toast('Listing price applied to the gap calculator. Confirm price and availability before relying on it.');
}

function applyProfileToListings() {
  const profile = window.funditProfile || {};
  const maxPrice = Number(profile.price);
  if (maxPrice > 0) {
    $('#listingMaxPrice').value = Math.round(maxPrice);
  } else {
    const power = calculation(get('rate')).power;
    if (power > 0) $('#listingMaxPrice').value = Math.round(power);
  }
  const beds = Number(profile.beds);
  if (beds > 0) $('#listingBeds').value = beds;
  const hoa = Number(profile.hoa);
  if (hoa > 0) $('#listingMaxHoa').value = Math.round(hoa);
  const city = (profile.cities || '').split(/[,;]/)[0].trim();
  if (city) {
    const option = [...$('#listingCity').options].find(item => item.value.toLowerCase() === city.toLowerCase());
    if (option) $('#listingCity').value = option.value;
  }
  const typeMap = { 'Single-family home': 'single_family', Condominium: 'condo', Townhouse: 'townhouse', Duplex: 'duplex', 'Manufactured home': 'manufactured' };
  if (typeMap[profile.property]) $('#listingType').value = typeMap[profile.property];
  renderListings(true);
}

initListings();
